{"code": "import os
import requests
import datetime
from dotenv import load_dotenv

load_dotenv('/home/runner/.hermes/.env')

APP_ID = os.environ.get('FEISHU_APP_ID')
APP_SECRET = os.environ.get('FEISHU_APP_SECRET')

def get_tenant_access_token():
    url = 'https://open.feishu.cn/open-apis/auth/v3/app_access_token/internal'
    payload = {
        'app_id': APP_ID,
        'app_secret': APP_SECRET
    }
    response = requests.post(url, json=payload)
    return response.json().get('tenant_access_token')

def get_calendar_events(token):
    # Today's date range
    today = datetime.date.today()
    start_time = int(datetime.datetime.combine(today, datetime.time.min).timestamp())
    end_time = int(datetime.datetime.combine(today, datetime.time.max).timestamp())

    url = 'https://open.feishu.cn/open-apis/calendar/v4/calendars/primary/events'
    headers = {
        'Authorization': f'Bearer {token}'
    }
    params = {
        'start_time': str(start_time),
        'end_time': str(end_time)
    }
    response = requests.get(url, headers=headers, params=params)
    return response.json()

token = get_tenant_access_token()
if token:
    events = get_calendar_events(token)
    print(f"Calendar Events: {events}")
else:
    print("Failed to get Feishu token.")
